sys_script.script:
(function executeRule(current, previous) {
    try {
        var obj = "Engagement request " + current.getValue('number') +
            " needs a triage rationale draft. Record sys_id: " + current.getUniqueValue() +
            ". Read its D/V/F signals and narratives and append ONE work note (the write tool " +
            "prefixes [AI Triage Draft]) with the per-axis read, the verbatim stamped assessment " +
            "citation, and a band-consistent next step. Journal write only; change no fields; never rate.";
        var resp = new sn_aia.AiAgentRuntimeUtil().startAiAgentConversation({
            targetRecordId: current.getUniqueValue(),
            targetTable: 'x_snc_ptag_engage_engagement_request',
            objective: obj,
            usecaseId: 'a915790d875e0b90e5790f29dabb354d',
            conversationUser: gs.getUserID()
        });
        if (!resp) { gs.warn('[PTAG triage] AI agent did not start for ' + current.getValue('number') + ' (refused by licensing or configuration); no draft written.'); } else { gs.info('[PTAG triage] start: ' + JSON.stringify(resp)); }
    } catch (e) {
        gs.warn('[PTAG triage] failed to start: ' + e);
    }
})(current, previous);
